// Returns a space-separated countdown string ending with "liftoff".
// countdown(3) -> "3 2 1 liftoff"
// countdown(1) -> "1 liftoff"
// countdown(0) -> "liftoff"
std::string countdown(int n)
{
    std::string result {};
    do
    {
        result += std::to_string(n);
        result += ' ';
        --n;
    } while (n > 0);
    result += "liftoff";
    return result;
}

