// Student file: function definitions only, no main()
#include <string>

// Maps a direction code to a hint string.
//   -1  -> "too low"
//    0  -> "correct"
//   +1  -> "too high"
// anything else -> "invalid"
std::string hintText(int code)
{
    switch (code)
    {
    case -1:
        return "too low";
    case 0:
        return "correct";
    case 1:
        return "too high";
    default:
        return "invalid";
    }
}
